SELECT percentile_cont(0.75) within GROUP (ORDER BY l.value) AS percentile_75 FROM labevents l JOIN admissions a ON l.subject_id = a.subject_id JOIN patients p ON a.subject_id = p.subject_id WHERE l.itemid = 261 AND p.gender = 2 AND EXTRACT(YEAR FROM a.dischtime) = EXTRACT(YEAR FROM CURRENT_DATE) - 45 AND a.admission_type_id IN (SELECT admission_type_id FROM admissions WHERE code = 'GI bleeding');